import{_ as e,o as n,c as t,a5 as s}from"./chunks/framework.Bkm3ODFN.js";const h=JSON.parse('{"title":"🔄 ZLMediaKit 流媒体集群对接","description":"","frontmatter":{},"headers":[],"relativePath":"media/zlmediakit.md","filePath":"media/zlmediakit.md","lastUpdated":1794271174000}'),l={name:"media/zlmediakit.md"};function i(p,a,r,d,o,c){return n(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="🔄-zlmediakit-流媒体集群对接" tabindex="-1">🔄 ZLMediaKit 流媒体集群对接 <a class="header-anchor" href="#🔄-zlmediakit-流媒体集群对接" aria-label="Permalink to &quot;🔄 ZLMediaKit 流媒体集群对接&quot;">​</a></h1><p><a href="https://github.com/ZLMediaKit/ZLMediaKit" target="_blank" rel="noreferrer">ZLMediaKit</a> 是一款基于 C++ 开发的高性能开源流媒体服务器，MzMedia 将其作为核心流媒体转码与分发节点。</p><hr><h2 id="_1-节点纳管架构" tabindex="-1">1. 节点纳管架构 <a class="header-anchor" href="#_1-节点纳管架构" aria-label="Permalink to &quot;1. 节点纳管架构&quot;">​</a></h2><ul><li>平台支持单机挂载或多流媒体节点集群纳管（通过 <code>wvp_media_server</code> 表管理）；</li><li>每个流媒体节点配置固定的 HTTP 端口、REST API 访问密钥（Secret）、Hook 回调地址以及动态 RTP 端口接收范围（推荐 <code>30000-30500</code>）。</li></ul><hr><h2 id="_2-实时点播推流时序-invite-协商" tabindex="-1">2. 实时点播推流时序 (INVITE 协商) <a class="header-anchor" href="#_2-实时点播推流时序-invite-协商" aria-label="Permalink to &quot;2. 实时点播推流时序 (INVITE 协商)&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端播放器          MzMedia 后端           ZLMediaKit           GB28181 摄像机</span></span>
<span class="line"><span>    │                    │                    │                      │</span></span>
<span class="line"><span>    │── 1. 点播请求 ────&gt;│                    │                      │</span></span>
<span class="line"><span>    │                    │── 2. openRtpServer&gt;│                      │</span></span>
<span class="line"><span>    │                    │&lt;──返回动态端口30002│                      │</span></span>
<span class="line"><span>    │                    │                                           │</span></span>
<span class="line"><span>    │                    │── 3. SIP INVITE (携带 ZLM 端口 SDP) ──────&gt;│</span></span>
<span class="line"><span>    │                    │&lt;── 4. 200 OK (携带摄像机 RTP 发送 SDP) ───│</span></span>
<span class="line"><span>    │                    │── 5. SIP ACK ────────────────────────────&gt;│</span></span>
<span class="line"><span>    │                    │                                           │</span></span>
<span class="line"><span>    │                    │                    │&lt;── 6. 推送 RTP 流 ───│</span></span>
<span class="line"><span>    │                    │&lt;── 7. Hook 通知 ───│                      │</span></span>
<span class="line"><span>    │&lt;── 8. 返回播放地址 ─│                    │                      │</span></span>
<span class="line"><span>    │ (WebRTC/FLV/HLS)   │                    │                      │</span></span>
<span class="line"><span>    │                    │                    │                      │</span></span>
<span class="line"><span>    │────────────────────┼── 9. 拉流播放 ────&gt;│                      │</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><hr><h2 id="_3-webhook-回调钩子体系" tabindex="-1">3. Webhook 回调钩子体系 <a class="header-anchor" href="#_3-webhook-回调钩子体系" aria-label="Permalink to &quot;3. Webhook 回调钩子体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Hook 名称</th><th style="text-align:left;">触发时机</th><th style="text-align:left;">MzMedia 业务处理逻辑</th></tr></thead><tbody><tr><td style="text-align:left;"><code>on_server_started</code></td><td style="text-align:left;">ZLMediaKit 进程启动/重启</td><td style="text-align:left;">重置流媒体节点在线状态，同步当前正在推流的任务。</td></tr><tr><td style="text-align:left;"><code>on_publish</code></td><td style="text-align:left;">设备开始向 ZLM 推送音视频流</td><td style="text-align:left;">校验流鉴权密钥，若通过则更新推流状态为活跃。</td></tr><tr><td style="text-align:left;"><code>on_play</code></td><td style="text-align:left;">前端播放器开始连接播放</td><td style="text-align:left;">记录播放会话，更新在线观看人数。</td></tr><tr><td style="text-align:left;"><code>on_stream_none_reader</code></td><td style="text-align:left;">某个视频流所有客户端均已断开</td><td style="text-align:left;"><strong>无人观看自动停流机制</strong>：超时后自动向摄像机下发 SIP <code>BYE</code> 指令，释放带宽与 RTP 端口。</td></tr><tr><td style="text-align:left;"><code>on_stream_not_found</code></td><td style="text-align:left;">前端请求播放不存在的流</td><td style="text-align:left;">触发自动按需拉流或提示流离线。</td></tr></tbody></table>`,11)])])}const m=e(l,[["render",i]]);export{h as __pageData,m as default};
